  /**
   * @method
   * @name bitopro#fetchCurrencies
   * @description fetches all available currencies on an exchange
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_currency_info.md
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an associative dictionary of currencies
   */
  std::shared_future<ccxt::any>
  fetchCurrencies(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response = awaitValue(
                            this->publicGetProvisioningCurrencies(params));
                        //
                        //     {
                        //         "data":[
                        //             {
                        //                 "currency":"eth",
                        //                 "withdrawFee":"0.007",
                        //                 "minWithdraw":"0.001",
                        //                 "maxWithdraw":"1000",
                        //                 "maxDailyWithdraw":"2000",
                        //                 "withdraw":true,
                        //                 "deposit":true,
                        //                 "depositConfirmation":"12"
                        //             }
                        //         ]
                        //     }
                        //
                        ccxt::any currencies = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseCurrencies(currencies);
                      })
        .share();
  }

  ccxt::any parseCurrency(ccxt::any rawCurrency) override {
    ccxt::any fiatCurrencies =
        this->handleOption(std::string("fetchCurrencies"),
                           std::string("fiatCurrencies"), ccxt::list{});
    ccxt::any currencyId =
        this->safeString(rawCurrency, std::string("currency"));
    ccxt::any code = this->safeCurrencyCode(currencyId);
    ccxt::any deposit = this->safeBool(rawCurrency, std::string("deposit"));
    ccxt::any withdraw = this->safeBool(rawCurrency, std::string("withdraw"));
    ccxt::any isFiat = this->inArray(code, fiatCurrencies);
    return this->safeCurrencyStructure(ccxt::dict{
        {std::string("id"), currencyId},
        {std::string("code"), code},
        {std::string("info"), rawCurrency},
        {std::string("type"),
         (isTrue(isFiat) ? ccxt::any(std::string("fiat"))
                         : ccxt::any(std::string("crypto")))},
        {std::string("name"), ccxt::any{}},
        {std::string("active"), (isTrue((isEqual(deposit, true))) &&
                                 isTrue((isEqual(withdraw, true))))},
        {std::string("deposit"), deposit},
        {std::string("withdraw"), withdraw},
        {std::string("fee"),
         this->safeNumber(rawCurrency, std::string("withdrawFee"))},
        {std::string("precision"), ccxt::any{}},
        {std::string("limits"),
         ccxt::dict{
             {std::string("withdraw"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(rawCurrency, std::string("minWithdraw"))},
                  {std::string("max"),
                   this->safeNumber(rawCurrency, std::string("maxWithdraw"))},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
         }},
        {std::string("networks"), ccxt::any{}},
    });
  }

  /**
   * @method
   * @name bitopro#fetchMarkets
   * @description retrieves data on all markets for bitopro
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_trading_pair_info.md
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response = awaitValue(
                            this->publicGetProvisioningTradingPairs());
                        ccxt::any markets = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        //
                        //     {
                        //         "data":[
                        //             {
                        //                 "pair":"shib_twd",
                        //                 "base":"shib",
                        //                 "quote":"twd",
                        //                 "basePrecision":"8",
                        //                 "quotePrecision":"6",
                        //                 "minLimitBaseAmount":"100000",
                        //                 "maxLimitBaseAmount":"5500000000",
                        //                 "minMarketBuyQuoteAmount":"1000",
                        //                 "orderOpenLimit":"200",
                        //                 "maintain":false,
                        //                 "orderBookQuotePrecision":"6",
                        //                 "orderBookQuoteScaleLevel":"5"
                        //             }
                        //         ]
                        //     }
                        //
                        return this->parseMarkets(markets);
                      })
        .share();
  }

  ccxt::any parseMarket(ccxt::any market) override {
    ccxt::any active =
        (!isEqual(this->safeBool(market, std::string("maintain")), true));
    ccxt::any id = this->safeString(market, std::string("pair"));
    if (isTrue(isEqual(id, ccxt::any{}))) {
      throw ExchangeError(
          toString(add(this->id, std::string(" parseMarket() missing id"))));
    }
    ccxt::any uppercaseId = toUpperCase(id);
    ccxt::any baseId = this->safeString(market, std::string("base"));
    ccxt::any quoteId = this->safeString(market, std::string("quote"));
    ccxt::any base = this->safeCurrencyCode(baseId);
    ccxt::any quote = this->safeCurrencyCode(quoteId);
    ccxt::any symbol = add(add(base, std::string("/")), quote);
    ccxt::any limits = ccxt::dict{
        {std::string("amount"),
         ccxt::dict{
             {std::string("min"),
              this->safeNumber(market, std::string("minLimitBaseAmount"))},
             {std::string("max"),
              this->safeNumber(market, std::string("maxLimitBaseAmount"))},
         }},
        {std::string("price"),
         ccxt::dict{
             {std::string("min"), ccxt::any{}},
             {std::string("max"), ccxt::any{}},
         }},
        {std::string("cost"),
         ccxt::dict{
             {std::string("min"), ccxt::any{}},
             {std::string("max"), ccxt::any{}},
         }},
        {std::string("leverage"),
         ccxt::dict{
             {std::string("min"), ccxt::any{}},
             {std::string("max"), ccxt::any{}},
         }},
    };
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("uppercaseId"), uppercaseId},
        {std::string("symbol"), symbol},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("baseId"), base},
        {std::string("quoteId"), quote},
        {std::string("settle"), ccxt::any{}},
        {std::string("settleId"), ccxt::any{}},
        {std::string("type"), std::string("spot")},
        {std::string("spot"), true},
        {std::string("margin"), false},
        {std::string("swap"), false},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("contract"), false},
        {std::string("linear"), ccxt::any{}},
        {std::string("inverse"), ccxt::any{}},
        {std::string("contractSize"), ccxt::any{}},
        {std::string("expiry"), ccxt::any{}},
        {std::string("expiryDatetime"), ccxt::any{}},
        {std::string("strike"), ccxt::any{}},
        {std::string("optionType"), ccxt::any{}},
        {std::string("limits"), limits},
        {std::string("precision"),
         ccxt::dict{
             {std::string("price"),
              this->parseNumber(this->parsePrecision(
                  this->safeString(market, std::string("quotePrecision"))))},
             {std::string("amount"),
              this->parseNumber(this->parsePrecision(
                  this->safeString(market, std::string("basePrecision"))))},
         }},
        {std::string("active"), active},
        {std::string("created"), ccxt::any{}},
        {std::string("info"), market},
    });
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "pair":"btc_twd",
    //         "lastPrice":"1182449.00000000",
    //         "isBuyer":false,
    //         "priceChange24hr":"-1.99",
    //         "volume24hr":"9.13089740",
    //         "high24hr":"1226097.00000000",
    //         "low24hr":"1181000.00000000"
    //     }
    //
    ccxt::any marketId = this->safeString(ticker, std::string("pair"));
    market = this->safeMarket(marketId, market);
    ccxt::any symbol = this->safeString(market, std::string("symbol"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), ccxt::any{}},
            {std::string("datetime"), ccxt::any{}},
            {std::string("high"),
             this->safeString(ticker, std::string("high24hr"))},
            {std::string("low"),
             this->safeString(ticker, std::string("low24hr"))},
            {std::string("bid"), ccxt::any{}},
            {std::string("bidVolume"), ccxt::any{}},
            {std::string("ask"), ccxt::any{}},
            {std::string("askVolume"), ccxt::any{}},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"), ccxt::any{}},
            {std::string("close"),
             this->safeString(ticker, std::string("lastPrice"))},
            {std::string("last"),
             this->safeString(ticker, std::string("lastPrice"))},
            {std::string("previousClose"), ccxt::any{}},
            {std::string("change"), ccxt::any{}},
            {std::string("percentage"),
             this->safeString(ticker, std::string("priceChange24hr"))},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"),
             this->safeString(ticker, std::string("volume24hr"))},
            {std::string("quoteVolume"), ccxt::any{}},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name bitopro#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_ticker_data.md
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("pair"),
                             ::getValue(market, std::string("id"))},
                        };
                        ccxt::any response =
                            awaitValue(this->publicGetTickersPair(
                                this->extend(request, params)));
                        ccxt::any ticker = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        //
                        //     {
                        //         "data":{
                        //             "pair":"btc_twd",
                        //             "lastPrice":"1182449.00000000",
                        //             "isBuyer":false,
                        //             "priceChange24hr":"-1.99",
                        //             "volume24hr":"9.13089740",
                        //             "high24hr":"1226097.00000000",
                        //             "low24hr":"1181000.00000000"
                        //         }
                        //     }
                        //
                        return this->parseTicker(ticker, market);
                      })
        .share();
  }

