  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchTrades
    //         {
    //                 "timestamp":1644651458,
    //                 "price":"1180785.00000000",
    //                 "amount":"0.00020000",
    //                 "isBuyer":false
    //         }
    //
    // fetchMyTrades
    //         {
    //                 "tradeId":"5685030251",
    //                 "orderId":"9669168142",
    //                 "price":"11821.8",
    //                 "action":"SELL",
    //                 "baseAmount":"0.01",
    //                 "quoteAmount":"118.218",
    //                 "fee":"0.236436",
    //                 "feeSymbol":"BNB",
    //                 "isTaker":true,
    //                 "timestamp":1644905714862,
    //                 "createdTimestamp":1644905714862
    //         }
    //
    ccxt::any id = this->safeString(trade, std::string("tradeId"));
    ccxt::any orderId = this->safeString(trade, std::string("orderId"));
    ccxt::any timestamp = ccxt::any{};
    if (isTrue(isEqual(id, ccxt::any{}))) {
      timestamp = this->safeTimestamp(trade, std::string("timestamp"));
    } else {
      timestamp = this->safeInteger(trade, std::string("timestamp"));
    }
    ccxt::any marketId = this->safeString(trade, std::string("pair"));
    market = this->safeMarket(marketId, market);
    ccxt::any symbol = this->safeString(market, std::string("symbol"));
    ccxt::any price = this->safeString(trade, std::string("price"));
    ccxt::any type = this->safeStringLower(trade, std::string("type"));
    ccxt::any side = this->safeStringLower(trade, std::string("action"));
    if (isTrue(isEqual(side, ccxt::any{}))) {
      ccxt::any isBuyer = this->safeBool(trade, std::string("isBuyer"));
      if (isTrue(isEqual(isBuyer, true))) {
        side = std::string("buy");
      } else {
        side = std::string("sell");
      }
    }
    ccxt::any amount = this->safeString(trade, std::string("amount"));
    if (isTrue(isEqual(amount, ccxt::any{}))) {
      amount = this->safeString(trade, std::string("baseAmount"));
    }
    ccxt::any fee = ccxt::any{};
    ccxt::any feeAmount = this->safeString(trade, std::string("fee"));
    ccxt::any feeSymbol = this->safeCurrencyCode(
        this->safeString(trade, std::string("feeSymbol")));
    if (isTrue(!isEqual(feeAmount, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeAmount},
          {std::string("currency"), feeSymbol},
          {std::string("rate"), ccxt::any{}},
      };
    }
    ccxt::any isTaker = this->safeBool(trade, std::string("isTaker"));
    ccxt::any takerOrMaker = ccxt::any{};
    if (isTrue(!isEqual(isTaker, ccxt::any{}))) {
      if (isTrue(isTaker)) {
        takerOrMaker = std::string("taker");
      } else {
        takerOrMaker = std::string("maker");
      }
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("info"), trade},
            {std::string("order"), orderId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("type"), type},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), fee},
        },
        market);
  }

