  /**
   * @method
   * @name bitopro#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_limitations_and_fees.md
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<ccxt::any>
  fetchTradingFees(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any response = awaitValue(
                     this->publicGetProvisioningLimitationsAndFees(params));
                 ccxt::any tradingFeeRate = this->safeDict(
                     response, std::string("tradingFeeRate"), ccxt::dict{});
                 ccxt::any first = this->safeValue(tradingFeeRate, 0);
                 //
                 //     {
                 //         "tradingFeeRate":[
                 //             {
                 //                 "rank":0,
                 //                 "twdVolumeSymbol":"\u003c",
                 //                 "twdVolume":"3000000",
                 //                 "bitoAmountSymbol":"\u003c",
                 //                 "bitoAmount":"7500",
                 //                 "makerFee":"0.001",
                 //                 "takerFee":"0.002",
                 //                 "makerBitoFee":"0.0008",
                 //                 "takerBitoFee":"0.0016"
                 //             }
                 //         ],
                 //         "orderFeesAndLimitations":[
                 //             {
                 //                 "pair":"BTC/TWD",
                 //                 "minimumOrderAmount":"0.0001",
                 //                 "minimumOrderAmountBase":"BTC",
                 //                 "minimumOrderNumberOfDigits":"0"
                 //             }
                 //         ],
                 //         "restrictionsOfWithdrawalFees":[
                 //             {
                 //                 "currency":"TWD",
                 //                 "fee":"15",
                 //                 "minimumTradingAmount":"100",
                 //                 "maximumTradingAmount":"1000000",
                 //                 "dailyCumulativeMaximumAmount":"2000000",
                 //                 "remarks":"",
                 //                 "protocol":""
                 //             }
                 //         ],
                 //         "cryptocurrencyDepositFeeAndConfirmation":[
                 //             {
                 //                 "currency":"TWD",
                 //                 "generalDepositFees":"0",
                 //                 "blockchainConfirmationRequired":""
                 //             }
                 //         ],
                 //         "ttCheckFeesAndLimitationsLevel1":[
                 //             {
                 //                 "currency":"TWD",
                 //                 "redeemDailyCumulativeMaximumAmount":"",
                 //                 "generateMinimumTradingAmount":"",
                 //                 "generateMaximumTradingAmount":"",
                 //                 "generateDailyCumulativeMaximumAmount":""
                 //             }
                 //         ],
                 //         "ttCheckFeesAndLimitationsLevel2":[
                 //             {
                 //                 "currency":"TWD",
                 //                 "redeemDailyCumulativeMaximumAmount":"20000000",
                 //                 "generateMinimumTradingAmount":"30",
                 //                 "generateMaximumTradingAmount":"10000000",
                 //                 "generateDailyCumulativeMaximumAmount":"10000000"
                 //             }
                 //         ]
                 //     }
                 //
                 ccxt::any result = ccxt::dict{};
                 ccxt::any maker =
                     this->safeNumber(first, std::string("makerFee"));
                 ccxt::any taker =
                     this->safeNumber(first, std::string("takerFee"));
                 ccxt::any symbols = this->symbols;
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(symbols));
                      postFixIncrement(i)) {
                   ccxt::any symbol = ::getValue(symbols, i);
                   ::setValue(result, symbol,
                              ccxt::dict{
                                  {std::string("info"), first},
                                  {std::string("symbol"), symbol},
                                  {std::string("maker"), maker},
                                  {std::string("taker"), taker},
                                  {std::string("percentage"), true},
                                  {std::string("tierBased"), true},
                              });
                 }
                 return result;
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    return ccxt::list{this->safeInteger(ohlcv, std::string("timestamp")),
                      this->safeNumber(ohlcv, std::string("open")),
                      this->safeNumber(ohlcv, std::string("high")),
                      this->safeNumber(ohlcv, std::string("low")),
                      this->safeNumber(ohlcv, std::string("close")),
                      this->safeNumber(ohlcv, std::string("volume"))};
  }

  /**
   * @method
   * @name bitopro#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_ohlc_data.md
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any resolution =
                     this->safeString(this->timeframes, timeframe, timeframe);
                 ccxt::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                     {std::string("resolution"), resolution},
                 };
                 // we need to have a limit argument because "to" and "from" are
                 // required
                 if (isTrue(isEqual(limit, ccxt::any{}))) {
                   limit = 500;
                 } else {
                   limit = mathMin(
                       limit, 75000); // supports slightly more than 75k candles
                                      // atm, but limit here to avoid errors
                 }
                 ccxt::any timeframeInSeconds = this->parseTimeframe(timeframe);
                 ccxt::any alignedSince = ccxt::any{};
                 if (isTrue(isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("to"), this->seconds());
                   ::setValue(request, std::string("from"),
                              subtract(::getValue(request, std::string("to")),
                                       (multiply(limit, timeframeInSeconds))));
                 } else {
                   ccxt::any timeframeInMilliseconds =
                       multiply(timeframeInSeconds, 1000);
                   alignedSince = multiply(
                       mathFloor(divide(since, timeframeInMilliseconds)),
                       timeframeInMilliseconds);
                   ::setValue(request, std::string("from"),
                              mathFloor(divide(since, 1000)));
                   ::setValue(
                       request, std::string("to"),
                       this->sum(::getValue(request, std::string("from")),
                                 multiply(limit, timeframeInSeconds)));
                 }
                 ccxt::any response =
                     awaitValue(this->publicGetTradingHistoryPair(
                         this->extend(request, params)));
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 //
                 //     {
                 //         "data":[
                 //             {
                 //                 "timestamp":1644581100000,
                 //                 "open":"1214737",
                 //                 "high":"1215110",
                 //                 "low":"1214737",
                 //                 "close":"1215110",
                 //                 "volume":"0.08423959"
                 //             }
                 //         ]
                 //     }
                 //
                 ccxt::any sparse =
                     this->parseOHLCVs(data, market, timeframe, since, limit);
                 return this->insertMissingCandles(sparse, timeframeInSeconds,
                                                   alignedSince, limit);
               })
        .share();
  }

  virtual ccxt::any insertMissingCandles(ccxt::any candles, ccxt::any distance,
                                         ccxt::any since, ccxt::any limit) {
    // the exchange doesn't send zero volume candles so we emulate them instead
    // otherwise sending a limit arg leads to unexpected results
    ccxt::any length = getArrayLength(candles);
    if (isTrue(isEqual(length, 0))) {
      return candles;
    }
    ccxt::any result = ccxt::list{};
    ccxt::any copyFrom = ::getValue(candles, 0);
    ccxt::any timestamp = ccxt::any{};
    if (isTrue(isEqual(since, ccxt::any{}))) {
      timestamp = ::getValue(copyFrom, 0);
    } else {
      timestamp = since;
    }
    ccxt::any i = 0;
    ccxt::any candleLength = getArrayLength(candles);
    ccxt::any resultLength = 0;
    while (isTrue((isLessThan(resultLength, limit))) &&
           isTrue((isLessThan(i, candleLength)))) {
      ccxt::any candle = ::getValue(candles, i);
      if (isTrue(isEqual(::getValue(candle, 0), timestamp))) {
        arrayPush(result, candle);
        i = this->sum(i, 1);
      } else {
        ccxt::any copy = this->arrayConcat(ccxt::list{}, copyFrom);
        ::setValue(copy, 0, timestamp);
        // set open, high, low to close
        ::setValue(copy, 1, ::getValue(copy, 4));
        ::setValue(copy, 2, ::getValue(copy, 4));
        ::setValue(copy, 3, ::getValue(copy, 4));
        ::setValue(copy, 5, this->parseNumber(std::string("0")));
        arrayPush(result, copy);
      }
      timestamp = this->sum(timestamp, multiply(distance, 1000));
      resultLength = getArrayLength(result);
      copyFrom = ::getValue(result, subtract(resultLength, 1));
    }
    return result;
  }

  ccxt::any parseBalance(ccxt::any response) override {
    //
    //     [{
    //         "currency":"twd",
    //         "amount":"0",
    //         "available":"0",
    //         "stake":"0",
    //         "tradable":true
    //     }]
    //
    ccxt::any result = ccxt::dict{
        {std::string("info"), response},
    };
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(response));
         postFixIncrement(i)) {
      ccxt::any balance = ::getValue(response, i);
      ccxt::any currencyId = this->safeString(balance, std::string("currency"));
      ccxt::any code = this->safeCurrencyCode(currencyId);
      ccxt::any amount = this->safeString(balance, std::string("amount"));
      ccxt::any available = this->safeString(balance, std::string("available"));
      ccxt::any account = ccxt::dict{
          {std::string("free"), available},
          {std::string("total"), amount},
      };
      if (isTrue(!isEqual(code, ccxt::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name bitopro#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/get_account_balance.md
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response =
                            awaitValue(this->privateGetAccountsBalance(params));
                        ccxt::any balances = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        //
                        //     {
                        //         "data":[
                        //             {
                        //                 "currency":"twd",
                        //                 "amount":"0",
                        //                 "available":"0",
                        //                 "stake":"0",
                        //                 "tradable":true
                        //             }
                        //         ]
                        //     }
                        //
                        return this->parseBalance(balances);
                      })
        .share();
  }

  virtual ccxt::any parseOrderStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("-1"), std::string("open")},
        {std::string("0"), std::string("open")},
        {std::string("1"), std::string("open")},
        {std::string("2"), std::string("closed")},
        {std::string("3"), std::string("closed")},
        {std::string("4"), std::string("canceled")},
        {std::string("6"), std::string("canceled")},
    };
    return (isTrue((isEqual(status, ccxt::any{})))
                ? ccxt::any(ccxt::any{})
                : ccxt::any(this->safeString(statuses, status)));
  }

  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    // createOrder
    //         {
    //             "orderId": "2220595581",
    //             "timestamp": "1644896744886",
    //             "action": "SELL",
    //             "amount": "0.01",
    //             "price": "15000",
    //             "timeInForce": "GTC"
    //         }
    //
    // fetchOrder
    //         {
    //             "id":"8777138788",
    //             "pair":"bnb_twd",
    //             "price":"16000",
    //             "avgExecutionPrice":"0",
    //             "action":"SELL",
    //             "type":"LIMIT",
    //             "timestamp":1644899002598,
    //             "status":4,
    //             "originalAmount":"0.01",
    //             "remainingAmount":"0.01",
    //             "executedAmount":"0",
    //             "fee":"0",
    //             "feeSymbol":"twd",
    //             "bitoFee":"0",
    //             "total":"0",
    //             "seq":"BNBTWD548774666",
    //             "timeInForce":"GTC",
    //             "createdTimestamp":1644898944074,
    //             "updatedTimestamp":1644899002598
    //         }
    //
    ccxt::any id =
        this->safeString2(order, std::string("id"), std::string("orderId"));
    ccxt::any timestamp = this->safeInteger2(order, std::string("timestamp"),
                                             std::string("createdTimestamp"));
    ccxt::any side = this->safeString(order, std::string("action"));
    if (isTrue(isEqual(side, ccxt::any{}))) {
      throw ExchangeError(toString(
          add(this->id, std::string(" parseOrder() returned no side"))));
    }
    side = toLowerCase(side);
    ccxt::any amount = this->safeString2(order, std::string("amount"),
                                         std::string("originalAmount"));
    ccxt::any price = this->safeString(order, std::string("price"));
    ccxt::any marketId = this->safeString(order, std::string("pair"));
    market = this->safeMarket(marketId, market, std::string("_"));
    ccxt::any symbol = this->safeString(market, std::string("symbol"));
    ccxt::any orderStatus = this->safeString(order, std::string("status"));
    ccxt::any status = this->parseOrderStatus(orderStatus);
    ccxt::any type = this->safeStringLower(order, std::string("type"));
    ccxt::any average =
        this->safeString(order, std::string("avgExecutionPrice"));
    ccxt::any filled = this->safeString(order, std::string("executedAmount"));
    ccxt::any remaining =
        this->safeString(order, std::string("remainingAmount"));
    ccxt::any timeInForce = this->safeString(order, std::string("timeInForce"));
    ccxt::any postOnly = ccxt::any{};
    if (isTrue(isEqual(timeInForce, std::string("POST_ONLY")))) {
      postOnly = true;
    }
    ccxt::any fee = ccxt::any{};
    ccxt::any feeAmount = this->safeString(order, std::string("fee"));
    ccxt::any feeSymbol = this->safeCurrencyCode(
        this->safeString(order, std::string("feeSymbol")));
    if (isTrue(ccxt::Precise::stringGt(feeAmount, std::string("0")))) {
      fee = ccxt::dict{
          {std::string("currency"), feeSymbol},
          {std::string("cost"), feeAmount},
      };
    }
    return this->safeOrder(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("clientOrderId"), ccxt::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"),
             this->safeInteger(order, std::string("updatedTimestamp"))},
            {std::string("symbol"), symbol},
            {std::string("type"), type},
            {std::string("timeInForce"), timeInForce},
            {std::string("postOnly"), postOnly},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("triggerPrice"), ccxt::any{}},
            {std::string("amount"), amount},
            {std::string("cost"), ccxt::any{}},
            {std::string("average"), average},
            {std::string("filled"), filled},
            {std::string("remaining"), remaining},
            {std::string("status"), status},
            {std::string("fee"), fee},
            {std::string("trades"), ccxt::any{}},
            {std::string("info"), order},
        },
        market);
  }

  /**
   * @method
   * @name bitopro#createOrder
   * @description create a trade order
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/create_an_order.md
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {object} [params.triggerPrice] the price at which a trigger order is
   * triggered at
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("type"), type},
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                     {std::string("action"), side},
                     {std::string("amount"),
                      this->amountToPrecision(symbol, amount)},
                     {std::string("timestamp"), this->milliseconds()},
                 };
                 ccxt::any orderType = toUpperCase(type);
                 if (isTrue(isEqual(orderType, std::string("LIMIT")))) {
                   ::setValue(request, std::string("price"),
                              this->priceToPrecision(symbol, price));
                 }
                 if (isTrue(isEqual(orderType, std::string("STOP_LIMIT")))) {
                   ::setValue(request, std::string("price"),
                              this->priceToPrecision(symbol, price));
                   ccxt::any triggerPrice =
                       this->safeValue2(params, std::string("triggerPrice"),
                                        std::string("stopPrice"));
                   params = this->omit(params,
                                       ccxt::list{std::string("triggerPrice"),
                                                  std::string("stopPrice")});
                   if (isTrue(isEqual(triggerPrice, ccxt::any{}))) {
                     throw InvalidOrder(toString(add(
                         add(add(this->id,
                                 std::string(" createOrder() requires a "
                                             "triggerPrice parameter for ")),
                             orderType),
                         std::string(" orders"))));
                   } else {
                     ::setValue(request, std::string("stopPrice"),
                                this->priceToPrecision(symbol, triggerPrice));
                   }
                   ccxt::any condition =
                       this->safeString(params, std::string("condition"));
                   if (isTrue(isEqual(condition, ccxt::any{}))) {
                     throw InvalidOrder(toString(
                         add(add(add(this->id,
                                     std::string(" createOrder() requires a "
                                                 "condition parameter for ")),
                                 orderType),
                             std::string(" orders"))));
                   } else {
                     ::setValue(request, std::string("condition"), condition);
                   }
                 }
                 ccxt::any postOnly =
                     this->isPostOnly(isEqual(orderType, std::string("MARKET")),
                                      ccxt::any{}, params);
                 if (isTrue(postOnly)) {
                   ::setValue(request, std::string("timeInForce"),
                              std::string("POST_ONLY"));
                 }
                 ccxt::any response = awaitValue(this->privatePostOrdersPair(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "orderId": "2220595581",
                 //         "timestamp": "1644896744886",
                 //         "action": "SELL",
                 //         "amount": "0.01",
                 //         "price": "15000",
                 //         "timeInForce": "GTC"
                 //     }
                 //
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name bitopro#cancelOrder
   * @description cancels an open order
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/cancel_an_order.md
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " cancelOrder() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("id"), id},
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response =
                     awaitValue(this->privateDeleteOrdersPairId(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "orderId":"8777138788",
                 //         "action":"SELL",
                 //         "timestamp":1644899002465,
                 //         "price":"16000",
                 //         "amount":"0.01"
                 //     }
                 //
                 return this->parseOrder(response, market);
               })
        .share();
  }

  virtual ccxt::any parseCancelOrders(ccxt::any data) {
    ccxt::any dataKeys = getObjectKeys(data);
    ccxt::any orders = ccxt::list{};
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(dataKeys));
         postFixIncrement(i)) {
      ccxt::any marketId = ::getValue(dataKeys, i);
      ccxt::any orderIds = ::getValue(data, marketId);
      for (ccxt::any j = 0; isLessThan(j, getArrayLength(orderIds));
           postFixIncrement(j)) {
        arrayPush(orders,
                  this->safeOrder(ccxt::dict{
                      {std::string("info"), ::getValue(orderIds, j)},
                      {std::string("id"), ::getValue(orderIds, j)},
                      {std::string("symbol"), this->safeSymbol(marketId)},
                  }));
      }
    }
    return orders;
  }

  /**
   * @method
   * @name bitopro#cancelOrders
   * @description cancel multiple orders
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/cancel_batch_orders.md
   * @param {string[]} ids order ids
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrders(ccxt::any ids, ccxt::any symbol = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " cancelOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any id = ::getValue(market, std::string("uppercaseId"));
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(id, ccxt::any{}))) {
                   ::setValue(request, id, ids);
                 }
                 ccxt::any response = awaitValue(
                     this->privatePutOrders(this->extend(request, params)));
                 //
                 //     {
                 //         "data":{
                 //             "BNB_TWD":[
                 //                 "5236347105",
                 //                 "359488711"
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"));
                 return this->parseCancelOrders(data);
               })
        .share();
  }

  /**
   * @method
   * @name bitopro#cancelAllOrders
   * @description cancel all open orders
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/cancel_all_orders.md
   * @param {string} [symbol] unified market symbol, only orders in the market
   * of this symbol are cancelled when symbol is not undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any request = ccxt::dict{};
                        ccxt::any response = ccxt::any{};
                        if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                          ccxt::any market = this->market(symbol);
                          ::setValue(request, std::string("pair"),
                                     ::getValue(market, std::string("id")));
                          response = awaitValue(this->privateDeleteOrdersPair(
                              this->extend(request, params)));
                        } else {
                          response = awaitValue(this->privateDeleteOrdersAll(
                              this->extend(request, params)));
                        }
                        ccxt::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        //
                        //     {
                        //         "data":{
                        //             "BNB_TWD":[
                        //                 "9515988421",
                        //                 "4639130027"
                        //             ]
                        //         }
                        //     }
                        //
                        return this->parseCancelOrders(data);
                      })
        .share();
  }

  /**
   * @method
   * @name bitopro#fetchOrder
   * @description fetches information on an order made by the user
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/get_an_order_data.md
   * @param {string} id the order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchOrder() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("orderId"), id},
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response =
                     awaitValue(this->privateGetOrdersPairOrderId(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "id":"8777138788",
                 //         "pair":"bnb_twd",
                 //         "price":"16000",
                 //         "avgExecutionPrice":"0",
                 //         "action":"SELL",
                 //         "type":"LIMIT",
                 //         "timestamp":1644899002598,
                 //         "status":4,
                 //         "originalAmount":"0.01",
                 //         "remainingAmount":"0.01",
                 //         "executedAmount":"0",
                 //         "fee":"0",
                 //         "feeSymbol":"twd",
                 //         "bitoFee":"0",
                 //         "total":"0",
                 //         "seq":"BNBTWD548774666",
                 //         "timeInForce":"GTC",
                 //         "createdTimestamp":1644898944074,
                 //         "updatedTimestamp":1644899002598
                 //     }
                 //
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name bitopro#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/get_orders_data.md
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTimestamp"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = awaitValue(this->privateGetOrdersAllPair(
                     this->extend(request, params)));
                 ccxt::any orders = this->safeList(
                     response, std::string("data"), ccxt::list{});
                 if (isTrue(isEqual(orders, ccxt::any{}))) {
                   orders = ccxt::list{};
                 }
                 //
                 //     {
                 //         "data":[
                 //             {
                 //                 "id":"2220595581",
                 //                 "pair":"bnb_twd",
                 //                 "price":"15000",
                 //                 "avgExecutionPrice":"0",
                 //                 "action":"SELL",
                 //                 "type":"LIMIT",
                 //                 "createdTimestamp":1644896744886,
                 //                 "updatedTimestamp":1644898706236,
                 //                 "status":4,
                 //                 "originalAmount":"0.01",
                 //                 "remainingAmount":"0.01",
                 //                 "executedAmount":"0",
                 //                 "fee":"0",
                 //                 "feeSymbol":"twd",
                 //                 "bitoFee":"0",
                 //                 "total":"0",
                 //                 "seq":"BNBTWD8540871774",
                 //                 "timeInForce":"GTC"
                 //             }
                 //         ]
                 //     }
                 //
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name bitopro#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/get_open_orders_data.md
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any request = ccxt::dict{};
                        ccxt::any market = ccxt::any{};
                        if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                          market = this->market(symbol);
                          ::setValue(request, std::string("pair"),
                                     ::getValue(market, std::string("id")));
                        }
                        ccxt::any response =
                            awaitValue(this->privateGetOrdersOpen(
                                this->extend(request, params)));
                        ccxt::any orders = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseOrders(orders, market, since, limit);
                      })
        .share();
  }

  /**
   * @method
   * @name bitopro#fetchClosedOrders
   * @description fetches information on multiple closed orders made by the user
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/get_orders_data.md
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any> fetchClosedOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any request = ccxt::dict{
                            {std::string("statusKind"), std::string("DONE")},
                        };
                        return this->fetchOrders(symbol, since, limit,
                                                 this->extend(request, params));
                      })
        .share();
  }

