  virtual ccxt::any parseTransactionStatus(ccxt::any status) {
    ccxt::any states = ccxt::dict{
        {std::string("COMPLETE"), std::string("ok")},
        {std::string("INVALID"), std::string("failed")},
        {std::string("PROCESSING"), std::string("pending")},
        {std::string("WAIT_PROCESS"), std::string("pending")},
        {std::string("FAILED"), std::string("failed")},
        {std::string("EXPIRED"), std::string("failed")},
        {std::string("CANCELLED"), std::string("failed")},
        {std::string("EMAIL_VERIFICATION"), std::string("pending")},
        {std::string("WAIT_CONFIRMATION"), std::string("pending")},
    };
    return this->safeString(states, status, status);
  }

  ccxt::any parseTransaction(ccxt::any transaction,
                             ccxt::any currency = ccxt::any{},
                             ccxt::any p2 = ccxt::any{},
                             ccxt::any p3 = ccxt::any{}) override {
    //
    // fetchDeposits
    //
    //    {
    //        "serial": "20220214X766799",
    //        "timestamp": "1644833015053",
    //        "address": "bnb1xml62k5a9dcewgc542fha75fyxdcp0zv8eqfsh",
    //        "amount": "0.20000000",
    //        "fee": "0.00000000",
    //        "total": "0.20000000",
    //        "status": "COMPLETE",
    //        "txid":
    //        "A3CC4F6828CC752B9F3737F48B5826B9EC2857040CB5141D0CC955F7E53DB6D9",
    //        "message": "778553959",
    //        "protocol": "MAIN",
    //        "id": "2905906537"
    //    }
    //
    // fetchWithdrawals || fetchWithdraw
    //
    //    {
    //        "serial": "20220215BW14069838",
    //        "timestamp": "1644907716044",
    //        "address": "TKrwMaZaGiAvtXCFT41xHuusNcs4LPWS7w",
    //        "amount": "8.00000000",
    //        "fee": "2.00000000",
    //        "total": "10.00000000",
    //        "status": "COMPLETE",
    //        "txid":
    //        "50bf250c71a582f40cf699fb58bab978437ea9bdf7259ff8072e669aab30c32b",
    //        "protocol": "TRX",
    //        "id": "9925310345"
    //    }
    //
    // withdraw
    //
    //    {
    //        "serial": "20220215BW14069838",
    //        "currency": "USDT",
    //        "protocol": "TRX",
    //        "address": "TKrwMaZaGiAvtXCFT41xHuusNcs4LPWS7w",
    //        "amount": "8",
    //        "fee": "2",
    //        "total": "10"
    //    }
    //
    ccxt::any currencyId = this->safeString(transaction, std::string("coin"));
    ccxt::any code = this->safeCurrencyCode(currencyId, currency);
    ccxt::any timestamp =
        this->safeInteger(transaction, std::string("timestamp"));
    ccxt::any address = this->safeString(transaction, std::string("address"));
    ccxt::any tag = this->safeString(transaction, std::string("message"));
    ccxt::any status = this->safeString(transaction, std::string("status"));
    ccxt::any networkId =
        this->safeString(transaction, std::string("protocol"));
    if (isTrue(isEqual(networkId, std::string("MAIN")))) {
      networkId = code;
    }
    return ccxt::dict{
        {std::string("info"), transaction},
        {std::string("id"),
         this->safeString(transaction, std::string("serial"))},
        {std::string("txid"),
         this->safeString(transaction, std::string("txid"))},
        {std::string("type"), ccxt::any{}},
        {std::string("currency"), code},
        {std::string("network"), this->networkIdToCode(networkId, code)},
        {std::string("amount"),
         this->safeNumber(transaction, std::string("total"))},
        {std::string("status"), this->parseTransactionStatus(status)},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("address"), address},
        {std::string("addressFrom"), ccxt::any{}},
        {std::string("addressTo"), address},
        {std::string("tag"), tag},
        {std::string("tagFrom"), ccxt::any{}},
        {std::string("tagTo"), tag},
        {std::string("updated"), ccxt::any{}},
        {std::string("comment"), ccxt::any{}},
        {std::string("internal"), ccxt::any{}},
        {std::string("fee"),
         ccxt::dict{
             {std::string("currency"), code},
             {std::string("cost"),
              this->safeNumber(transaction, std::string("fee"))},
             {std::string("rate"), ccxt::any{}},
         }},
    };
  }

